def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for br in range(h // 3):
        row = []
        for bc in range(w // 3):
            counts = {}
            for r in range(br * 3, br * 3 + 3):
                for c in range(bc * 3, bc * 3 + 3):
                    v = grid[r][c]
                    if v not in (0, 5):
                        counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 0)
        out.append(row)
    return out
